#include <iostream>
#include <memory>
#include <utility>

int main() {
    auto first = std::make_unique<int>(6);
    auto second = std::move(first);
    std::cout << *second << "\n";
    std::cout << std::boolalpha << (first == nullptr) << "\n";
}

#include <iostream>
#include <memory>

int main() {
    auto first = std::make_shared<int>(4);
    auto second = first;
    *second = 9;
    std::cout << *first << "\n";
}
